class Emitter {
  #events = new Map();

  on(name, fn) {
    if (typeof fn !== 'function') throw new TypeError('listener must be a function');
    if (!this.#events.has(name)) this.#events.set(name, []);
    this.#events.get(name).push(fn);
    return this;
  }

  off(name, fn) {
    const list = this.#events.get(name);
    if (!list) return this;
    // remove the LAST matching listener, like Node does
    for (let i = list.length - 1; i >= 0; i--) {
      if (list[i] === fn || list[i].original === fn) {
        list.splice(i, 1);
        break;
      }
    }
    if (list.length === 0) this.#events.delete(name);
    return this;
  }

  once(name, fn) {
    const wrapper = (...args) => {
      this.off(name, wrapper);
      fn.apply(this, args);
    };
    wrapper.original = fn;
    return this.on(name, wrapper);
  }

  emit(name, ...args) {
    const list = this.#events.get(name);
    if (!list || list.length === 0) {
      if (name === 'error') throw args[0] instanceof Error ? args[0] : new Error('Unhandled error');
      return false;
    }
    for (const fn of [...list]) fn.apply(this, args);
    return true;
  }

  listenerCount(name) {
    return this.#events.get(name)?.length ?? 0;
  }
}

