function throttle(fn, wait) {
  let last = 0;
  let timer = null;
  let pendingArgs = null;
  let pendingThis = null;

  function run(ctx, args) {
    last = Date.now();
    fn.apply(ctx, args);
  }

  function throttled(...args) {
    const remaining = wait - (Date.now() - last);
    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      run(this, args); // leading edge
    } else {
      pendingArgs = args;
      pendingThis = this;
      if (!timer) {
        timer = setTimeout(() => {
          timer = null;
          const a = pendingArgs;
          const t = pendingThis;
          pendingArgs = pendingThis = null;
          run(t, a); // trailing edge, latest args
        }, remaining);
      }
    }
  }

  throttled.cancel = () => {
    clearTimeout(timer);
    timer = null;
    pendingArgs = pendingThis = null;
    last = 0;
  };
  return throttled;
}

