const { setTimeout: sleep } = require('node:timers/promises');

const RETRYABLE_CODES = new Set(['ECONNRESET', 'ETIMEDOUT', 'ECONNREFUSED', 'EAI_AGAIN']);

function defaultShouldRetry(err) {
  if (err.name === 'AbortError') return false;
  if (RETRYABLE_CODES.has(err.code)) return true;
  const status = err.status ?? err.statusCode;
  return status === 429 || (status >= 500 && status <= 599);
}

async function retry(fn, {
  retries = 3,
  base = 100,
  cap = 10_000,
  shouldRetry = defaultShouldRetry,
  onRetry = () => {},
  signal,
} = {}) {
  for (let attempt = 0; ; attempt++) {
    signal?.throwIfAborted();
    try {
      return await fn({ attempt, signal });
    } catch (err) {
      if (attempt >= retries || !shouldRetry(err)) throw err;
      const exp = Math.min(cap, base * 2 ** attempt);
      let delay = Math.random() * exp; // full jitter
      if (err.retryAfterMs) delay = Math.max(delay, err.retryAfterMs);
      onRetry({ err, attempt: attempt + 1, delay });
      await sleep(delay, undefined, { signal }); // rejects if aborted
    }
  }
}

