const kCustom = Symbol.for('nodejs.util.promisify.custom'); // same as util.promisify.custom

function promisify(fn) {
  if (typeof fn !== 'function') throw new TypeError('fn must be a function');
  if (typeof fn[kCustom] === 'function') return fn[kCustom];

  function promisified(...args) {
    return new Promise((resolve, reject) => {
      fn.call(this, ...args, (err, value) => {
        if (err) reject(err);
        else resolve(value);
      });
    });
  }
  // keep the same prototype so it still looks like the original kind of function
  Object.setPrototypeOf(promisified, Object.getPrototypeOf(fn));
  return promisified;
}

