function rateLimit({ capacity = 10, refillPerSec = 5, keyFn = (req) => req.ip } = {}) {
  const buckets = new Map();
  // A bucket idle this long has refilled completely, so deleting it changes nothing.
  const idleMs = Math.ceil((capacity / refillPerSec) * 1000);

  const sweeper = setInterval(() => {
    const cutoff = Date.now() - idleMs;
    for (const [key, b] of buckets) if (b.last < cutoff) buckets.delete(key);
  }, Math.max(idleMs, 10_000));
  sweeper.unref(); // do not keep the process alive just for cleanup

  return function rateLimiter(req, res, next) {
    const key = keyFn(req);
    const now = Date.now();
    let b = buckets.get(key);
    if (!b) {
      b = { tokens: capacity, last: now };
      buckets.set(key, b);
    }

    const elapsedSec = (now - b.last) / 1000;
    b.tokens = Math.min(capacity, b.tokens + elapsedSec * refillPerSec);
    b.last = now;

    res.setHeader('RateLimit-Limit', capacity);
    if (b.tokens >= 1) {
      b.tokens -= 1;
      res.setHeader('RateLimit-Remaining', Math.floor(b.tokens));
      return next();
    }

    const waitSec = Math.ceil((1 - b.tokens) / refillPerSec);
    res.setHeader('RateLimit-Remaining', 0);
    res.setHeader('Retry-After', waitSec);
    res.status(429).json({ error: 'Too Many Requests' });
  };
}

// usage
const express = require('express');
const app = express();
app.set('trust proxy', 1); // one proxy hop (e.g. a load balancer) in front of us
app.use('/api', rateLimit({ capacity: 20, refillPerSec: 10 }));

