const fs = require('node:fs');
const readline = require('node:readline');

// Fast: byte-level, no string decoding, constant memory.
async function countFile(path) {
  let lines = 0, words = 0, bytes = 0;
  let inWord = false;
  let lastByte = -1;

  for await (const chunk of fs.createReadStream(path)) {
    bytes += chunk.length;
    for (let i = 0; i < chunk.length; i++) {
      const c = chunk[i];
      if (c === 0x0a) lines++;
      const isSpace = c === 0x20 || c === 0x0a || c === 0x09 || c === 0x0d;
      if (isSpace) inWord = false;
      else if (!inWord) { inWord = true; words++; }
    }
    lastByte = chunk[chunk.length - 1];
  }
  if (bytes > 0 && lastByte !== 0x0a) lines++; // last line has no newline
  return { lines, words, bytes };
}

// Simple: readline does the line splitting and \r\n handling for you.
async function countWithReadline(path) {
  const rl = readline.createInterface({
    input: fs.createReadStream(path),
    crlfDelay: Infinity,
  });
  let lines = 0, words = 0;
  for await (const line of rl) {
    lines++;
    words += line.split(/\s+/).filter(Boolean).length;
  }
  return { lines, words };
}

