class TTLCache {
  #map = new Map();
  #ttl;
  #max;

  constructor({ ttlMs, max = 10_000, sweepMs = 60_000 }) {
    this.#ttl = ttlMs;
    this.#max = max;
    const t = setInterval(() => this.#sweep(), sweepMs);
    t.unref();
  }

  get(key) {
    const e = this.#map.get(key);
    if (!e) return undefined;
    if (Date.now() >= e.expires) {
      this.#map.delete(key);
      return undefined;
    }
    return e.value;
  }

  set(key, value, ttlMs = this.#ttl) {
    this.#map.delete(key); // refresh insertion order
    this.#map.set(key, { value, expires: Date.now() + ttlMs });
    if (this.#map.size > this.#max) {
      this.#map.delete(this.#map.keys().next().value); // drop oldest
    }
  }

  delete(key) {
    return this.#map.delete(key);
  }

  #sweep() {
    const now = Date.now();
    for (const [k, e] of this.#map) if (now >= e.expires) this.#map.delete(k);
  }
}

function memoizeAsync(fn, { ttlMs = 60_000, key = (...args) => JSON.stringify(args) } = {}) {
  const done = new TTLCache({ ttlMs }); // settled values
  const inFlight = new Map();          // key -> pending promise

  return async function memoized(...args) {
    const k = key(...args);
    const cached = done.get(k);
    if (cached !== undefined) return cached.value;
    if (inFlight.has(k)) return inFlight.get(k);

    const p = (async () => fn.apply(this, args))()
      .then((value) => {
        done.set(k, { value }); // TTL starts now, when data arrived
        return value;
      })
      .finally(() => inFlight.delete(k)); // on error nothing is cached
    inFlight.set(k, p);
    return p;
  };
}

