class TimeoutError extends Error {
  constructor(message) {
    super(message);
    this.name = 'TimeoutError';
  }
}

function withTimeout(task, ms, { signal: parent } = {}) {
  const controller = new AbortController();
  const signal = parent
    ? AbortSignal.any([parent, controller.signal])
    : controller.signal;

  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => {
      const err = new TimeoutError(`timed out after ${ms}ms`);
      controller.abort(err); // cancel the work
      reject(err);           // and stop waiting
    }, ms);
  });

  // Promise.resolve().then(...) turns a sync throw in task into a rejection
  const work = Promise.resolve().then(() => task(signal));
  return Promise.race([work, timeout]).finally(() => clearTimeout(timer));
}

// One-liner alternative for APIs that accept a signal:
